def transform(grid):
    n = len(grid)
    # Colors form a repeating sequence along diagonals of constant r+c.
    # Collect the colors on each such diagonal.
    marks = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                marks.setdefault(r + c, []).append(v)

    # Use the smallest period consistent with every marked diagonal.
    # Multiple colors on one diagonal are treated as evidence for that
    # diagonal's observed color sequence position.
    vals = {s: max(set(vs), key=vs.count) for s, vs in marks.items()}
    period = 1
    for p in range(1, 2*n + 1):
        groups = {}
        good = True
        for s, v in vals.items():
            q = s % p
            if q in groups and groups[q] != v:
                good = False
                break
            groups[q] = v
        if good:
            period = p
            break

    known = {}
    for s, v in vals.items():
        known[s % period] = v

    # Continue the repeating color sequence through unobserved positions,
    # choosing the closest known phase.
    phases = list(known)
    def color_at(s):
        q = s % period
        if q in known:
            return known[q]
        nearest = min(phases, key=lambda x: min((q-x) % period, (x-q) % period))
        return known[nearest]

    return [[color_at(r+c) for c in range(n)] for r in range(n)]
